/* Palette: deep navy background, warm cream card, amber stars, slate text, soft red error */
:root {
  --bg: #1e293b;
  --card: #fef3c7;
  --card-text: #1e293b;
  --accent: #f59e0b;
  --accent-hover: #d97706;
  --star-off: #cbd5e1;
  --star-on: #f59e0b;
  --error: #dc2626;
  --border: #e2e8f0;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  padding: 16px;
}

.card {
  background: var(--card);
  color: var(--card-text);
  padding: 24px 20px;
  border-radius: var(--radius);
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  width: 100%;
  max-width: 520px;
}

h1 { margin: 0 0 4px; font-size: 1.6rem; }
.product-name { margin: 0 0 20px; font-weight: 600; color: #475569; }

fieldset {
  border: none;
  padding: 0;
  margin: 0 0 16px;
}

legend {
  font-weight: 600;
  margin-bottom: 8px;
  padding: 0;
}

.stars {
  display: flex;
  gap: 4px;
}

.star {
  background: none;
  border: none;
  font-size: 2rem;
  line-height: 1;
  cursor: pointer;
  color: var(--star-off);
  padding: 4px;
  border-radius: 6px;
  transition: color 0.15s, transform 0.1s;
}

.star:hover,
.star.hovered,
.star.selected {
  color: var(--star-on);
}

.star:active { transform: scale(0.9); }

.star:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 2px;
}

.status {
  margin: 4px 0 0;
  font-size: 0.9rem;
  color: #475569;
}

.field { margin-bottom: 16px; }

label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
}

textarea {
  width: 100%;
  padding: 10px 12px;
  font-family: var(--font);
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  resize: vertical;
  background: #fff;
  color: var(--card-text);
}

textarea:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 1px;
  border-color: var(--accent-hover);
}

.submit-btn {
  display: inline-block;
  width: 100%;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.submit-btn:hover { background: var(--accent-hover); }
.submit-btn:active { transform: scale(0.98); }
.submit-btn:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 2px;
}

.error {
  color: var(--error);
  font-size: 0.9rem;
  margin: 8px 0 0;
}

.reviews-section { margin-top: 28px; }

.reviews-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 8px;
  margin-bottom: 12px;
}

.reviews-header h2 { margin: 0; font-size: 1.2rem; }
.average { margin: 0; font-weight: 600; color: #475569; }

.review-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 300px;
  overflow-y: auto;
}

.review-item {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
}

.review-stars {
  color: var(--star-on);
  font-size: 1.1rem;
  letter-spacing: 2px;
}

.review-comment {
  margin: 4px 0 0;
  word-break: break-word;
}

.empty-state {
  color: #64748b;
  font-style: italic;
  text-align: center;
  padding: 16px 0;
}

[hidden] { display: none !important; }

@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.4rem; }
  .star { font-size: 1.8rem; }
}

(function () {
  'use strict';

  const starGroup = document.getElementById('starGroup');
  const stars = Array.from(starGroup.querySelectorAll('.star'));
  const ratingStatus = document.getElementById('ratingStatus');
  const commentInput = document.getElementById('comment');
  const form = document.getElementById('reviewForm');
  const formError = document.getElementById('formError');
  const reviewList = document.getElementById('reviewList');
  const emptyState = document.getElementById('emptyState');
  const averageDisplay = document.getElementById('averageDisplay');

  let selectedRating = 0;
  const reviews = [];

  function updateStars(highlightCount) {
    stars.forEach((star, i) => {
      const value = i + 1;
      star.classList.toggle('hovered', highlightCount > 0 && value <= highlightCount);
      star.classList.toggle('selected', highlightCount === 0 && value <= selectedRating);
      star.setAttribute('aria-checked', value === selectedRating ? 'true' : 'false');
      star.tabIndex = value === (selectedRating || 1) ? 0 : -1;
    });
  }

  function setRating(value) {
    selectedRating = value;
    ratingStatus.textContent = value ? `You rated ${value} star${value > 1 ? 's' : ''}` : 'No rating selected';
    updateStars(0);
  }

  stars.forEach((star, i) => {
    star.addEventListener('mouseenter', () => updateStars(i + 1));
    star.addEventListener('mouseleave', () => updateStars(0));
    star.addEventListener('click', () => setRating(i + 1));
    star.addEventListener('keydown', (e) => {
      let newRating = selectedRating || 1;
      if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
        e.preventDefault();
        newRating = Math.min(5, newRating + 1);
        setRating(newRating);
        stars[newRating - 1].focus();
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
        e.preventDefault();
        newRating = Math.max(1, newRating - 1);
        setRating(newRating);
        stars[newRating - 1].focus();
      } else if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        setRating(i + 1);
      }
    });
  });

  function updateAverage() {
    if (reviews.length === 0) {
      averageDisplay.textContent = 'Average: —';
      return;
    }
    const sum = reviews.reduce((acc, r) => acc + r.rating, 0);
    const avg = (sum / reviews.length).toFixed(1);
    averageDisplay.textContent = `Average: ${avg} / 5 (${reviews.length} review${reviews.length > 1 ? 's' : ''})`;
  }

  function addReviewToList(rating, comment) {
    if (emptyState && emptyState.parentNode) emptyState.remove();
    const li = document.createElement('li');
    li.className = 'review-item';
    const starSpan = document.createElement('span');
    starSpan.className = 'review-stars';
    starSpan.textContent = '★'.repeat(rating) + '☆'.repeat(5 - rating);
    starSpan.setAttribute('aria-label', `${rating} out of 5 stars`);
    const commentP = document.createElement('p');
    commentP.className = 'review-comment';
    commentP.textContent = comment;
    li.appendChild(starSpan);
    li.appendChild(commentP);
    reviewList.appendChild(li);
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    formError.hidden = true;
    const comment = commentInput.value.trim();
    if (selectedRating === 0) {
      formError.textContent = 'Please select a star rating.';
      formError.hidden = false;
      return;
    }
    if (!comment) {
      formError.textContent = 'Please write a comment.';
      formError.hidden = false;
      return;
    }
    reviews.push({ rating: selectedRating, comment });
    addReviewToList(selectedRating, comment);
    updateAverage();
    setRating(0);
    commentInput.value = '';
    commentInput.focus();
  });

  // Initialize tab indices
  updateStars(0);
})();
